// The entries of the built-in catalog, read as syntax for the gates that look at them (W5-02). Nothing is executed.
//
// apps/workbench/src/builtin-plugins.ts is generated by scripts/generate-plugin-registry.mjs: it imports `registration` from
// each built-in plugin package's `./registration` subpath and lists those, and an entry is the object literal that package's
// src/registration.ts exports. An entry written as an object literal in the catalog's own array is read as well: the gates
// measure the merge-base with the head's scripts, and a merge-base from before W5-02 writes the catalog by hand.
import path from "node:path";
import ts from "typescript";

export const CATALOG = "apps/workbench/src/builtin-plugins.ts";
const SUBPATH = "/registration";
const PACKAGE_MANIFEST = /^plugins\/native\/[^/]+\/package\.json$/;

const parse = (file, text) => ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
const unwrap = (node) => {
  while (node && (ts.isParenthesizedExpression(node) || ts.isAsExpression(node) || ts.isSatisfiesExpression(node))) node = node.expression;
  return node;
};
const exportedObject = (tree, name) => {
  for (const statement of tree.statements) {
    if (!ts.isVariableStatement(statement) || !statement.modifiers?.some((item) => item.kind === ts.SyntaxKind.ExportKeyword)) continue;
    for (const declaration of statement.declarationList.declarations) {
      if (ts.isIdentifier(declaration.name) && declaration.name.text === name) return unwrap(declaration.initializer) ?? null;
    }
  }
  return null;
};
const namedImports = (tree) => {
  const imports = new Map();
  for (const statement of tree.statements) {
    const bindings = ts.isImportDeclaration(statement) && !statement.importClause?.isTypeOnly ? statement.importClause?.namedBindings : null;
    if (bindings && ts.isNamedImports(bindings)) for (const item of bindings.elements) {
      imports.set(item.name.text, { specifier: statement.moduleSpecifier.text, imported: (item.propertyName ?? item.name).text });
    }
  }
  return imports;
};
// Package name -> directory, for the built-in plugin packages of a snapshot ({ files, read }).
const packageDirectories = (snapshot) => {
  const directories = new Map();
  for (const file of snapshot.files ?? []) {
    if (!PACKAGE_MANIFEST.test(file)) continue;
    let name;
    try { name = JSON.parse(snapshot.read(file) ?? "null")?.name; } catch { continue; }
    if (typeof name === "string") directories.set(name, path.posix.dirname(file));
  }
  return directories;
};

/**
 * Each entry of BUILTIN_PLUGIN_CATALOG as `{ file, object }`: the entry's object literal and the file it is written in (the
 * plugin's src/registration.ts, or the catalog itself for an entry written in place). A catalog that is missing, or has no
 * array, has no entries; an entry that is neither form throws, so a gate never counts a catalog it could not read.
 */
export function catalogEntries(snapshot) {
  const text = snapshot.read(CATALOG);
  if (text === null) return [];
  const tree = parse(CATALOG, text), array = exportedObject(tree, "BUILTIN_PLUGIN_CATALOG");
  if (!array || !ts.isArrayLiteralExpression(array)) return [];
  const imports = namedImports(tree);
  let directories = null;
  return array.elements.map((element) => {
    const node = unwrap(element);
    if (ts.isObjectLiteralExpression(node)) return { file: CATALOG, object: node };
    const from = ts.isIdentifier(node) ? imports.get(node.text) : undefined;
    if (!from || from.imported !== "registration" || !from.specifier.endsWith(SUBPATH)) {
      throw new Error(`${CATALOG}: catalog entry ${node.getText()} is neither an object literal nor a plugin's imported registration`);
    }
    directories ??= packageDirectories(snapshot);
    const directory = directories.get(from.specifier.slice(0, -SUBPATH.length));
    const file = directory ? `${directory}/src/registration.ts` : null, source = file ? snapshot.read(file) : null;
    if (source === null) throw new Error(`${CATALOG}: ${from.specifier} is not a built-in plugin's src/registration.ts in this tree`);
    const object = exportedObject(parse(file, source), "registration");
    if (!object || !ts.isObjectLiteralExpression(object)) throw new Error(`${file}: \`registration\` is not exported as an object literal`);
    return { file, object };
  });
}

/** The entries written as the catalog's own array would hold them, for the text checks of scripts/check-package-boundaries.mjs. */
export function catalogText(snapshot) {
  return `export const BUILTIN_PLUGIN_CATALOG = [\n${catalogEntries(snapshot).map(({ object }) => `${object.getText()},`).join("\n")}\n];\n`;
}
